package com.mustafakoceerr.tilepdf.feature.about.navigation

import androidx.annotation.RawRes
import androidx.navigation.NavController
import androidx.navigation.NavGraphBuilder
import androidx.navigation.compose.composable
import com.mustafakoceerr.tilepdf.feature.about.AboutScreen
import kotlinx.serialization.Serializable

@Serializable
data object AboutRoute

fun NavController.navigateToAbout() = navigate(AboutRoute)

/** @param librariesRes the app's `R.raw.aboutlibraries`, generated by AboutLibraries. */
fun NavGraphBuilder.aboutScreen(onBack: () -> Unit, @RawRes librariesRes: Int) {
    composable<AboutRoute> {
        AboutScreen(onBack = onBack, librariesRes = librariesRes)
    }
}
